{code:java}
BigDecimal qoh = inventoryItem.getBigDecimal('quantityOnHandTotal') ?: 0.0
if (qoh > 0) {
    quantityIssued = (parameters.quantity == null || parameters.quantity > qoh) ? qoh : parameters.quantity
    ...
}
{code}
